SINA_SMART["anat2-biliary"] = {"lecture":"anat2-biliary","title":"The biliary system","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat2-biliary:e0","text":"Bile: 600-1000 mL/day; bilirubin from haemoglobin; enterohepatic circulation via ileum.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-biliary:e1","text":"Intrahepatic ducts follow segments; variants common.","topic":"Intrahepatic ducts and confluence","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-biliary:e2","text":"Confluence at the hilum within the hilar plate; left duct long, right duct short.","topic":"Intrahepatic ducts and confluence","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-biliary:e3","text":"Common hepatic + cystic → common bile duct.","topic":"Extrahepatic ducts and gallbladder","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-biliary:e4","text":"CBD: hepatoduodenal ligament → retroduodenal → intrapancreatic → ampulla → D2.","topic":"Extrahepatic ducts and gallbladder","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-biliary:e5","text":"Sphincter of Oddi at the major papilla.","topic":"Extrahepatic ducts and gallbladder","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-biliary:e6","text":"Gallbladder under segments 4b-5: fundus, body, neck; valve of Heister.","topic":"Extrahepatic ducts and gallbladder","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-biliary:e7","text":"Hepatocystic triangle + cystic artery; critical view of safety.","topic":"Extrahepatic ducts and gallbladder","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-biliary:e8","text":"Cystic artery supplies the gallbladder.","topic":"Extrahepatic ducts and gallbladder","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-biliary:e9","text":"Sympathetic: storage, pain; vagus: release; right phrenic: Glisson's capsule.","topic":"Vessels, nerves and lymph","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"10a6emm":"a","10eq4kw":"a","1n270u5":"a","uejdil":"a","1o62fxz":"a","5ar0ej":"a","s796rq":"a","bynpm7":"a","d0euts":"a","x15h7n":"a","1ufkve0":"a","gubukb":"a"},"mapCounts":{"verified":0,"auto":12,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat2-biliary:e0":{"s":0,"u":["Bile: 600-1000 mL/day; bilirubin from haemoglobin; enterohepatic circulation via ileum.","Bile salts are reabsorbed in the ileum and return to the liver via the portal vein: the enterohepatic circulation .","Bile (water, electrolytes, bile acids, cholesterol, phospholipids and pigments, mainly bilirubin from haemoglobin breakdown) is made continuously by the liver, 600-1000 mL/day , stored and concentrated in the gallbladder and released when food, especially fat, enters the duodenum."],"dp":[{"h":"Note","t":"Bile : 600-1000 mL/day; enterohepatic circulation : bile salts reabsorbed in the terminal ileum → portal vein → liver. CCK contracts the gallbladder; vagus promotes release."}]},"anat2-biliary:e1":{"s":1,"u":["Intrahepatic ducts follow segments; variants common.","Intrahepatic ducts follow the functional segments , running in the portal triads within Glisson's capsule (subsegmental → segmental → sectoral ducts); anatomical variants are frequent and create injury risk in liver surgery and cholecystectomy."],"dp":[]},"anat2-biliary:e2":{"s":1,"u":["Confluence at the hilum within the hilar plate; left duct long, right duct short.","At the hilum, the right and left hepatic ducts join (the biliary confluence ) over the origin of the right portal vein, in front of and above the right hepatic artery, within the hilar plate (connective tissue fused with Glisson's capsule).","The right duct is short; the left duct has a long extrahepatic course under the quadrate lobe, which surgeons use for repairs."],"dp":[]},"anat2-biliary:e3":{"s":2,"u":["Common hepatic + cystic → common bile duct.","The common hepatic duct runs in the hepatoduodenal ligament and joins the cystic duct to form the common bile duct , which passes behind the duodenum and through the head of the pancreas to the hepatopancreatic ampulla , opening into the descending duodenum at the major duodenal papilla , controlled by the sphincter of Oddi (accessible by endoscopy: stone extraction, sphincterotomy).","The hepatocystic triangle (liver, cystic duct, common hepatic duct), crossed by the cystic artery (related to Calot's triangle), must be dissected to obtain the critical view of safety before clipping anything in a cholecystectomy."],"dp":[{"h":"Why a gallstone can cause jaundice and pancreatitis","t":"The common bile duct and the main pancreatic duct usually join at the hepatopancreatic ampulla before opening into the duodenum. A stone lodged there blocks bile, so bilirubin backs up into the blood (jaundice), and can also block or divert pancreatic juice, triggering acute pancreatitis. This shared exit explains why gallstones are a leading cause of both. Source: the lecture's hepatopancreatic ampulla slide."},{"h":"Note","t":"Right + left hepatic ducts → common hepatic duct ; + cystic duct → common bile duct → behind D1 → through the pancreatic head → joins the pancreatic duct at the ampulla of Vater → major papilla (D2) , controlled by the sphincter of Oddi ."},{"h":"Clinical","t":"Cholecystectomy danger: mistaking the common bile duct for the cystic duct, or the right hepatic artery for the cystic artery; biliary and arterial variants are common."}]},"anat2-biliary:e4":{"s":2,"u":["CBD: hepatoduodenal ligament → retroduodenal → intrapancreatic → ampulla → D2.","The common hepatic duct runs in the hepatoduodenal ligament and joins the cystic duct to form the common bile duct , which passes behind the duodenum and through the head of the pancreas to the hepatopancreatic ampulla , opening into the descending duodenum at the major duodenal papilla , controlled by the sphincter of Oddi (accessible by endoscopy: stone extraction, sphincterotomy)."],"dp":[]},"anat2-biliary:e5":{"s":2,"u":["Sphincter of Oddi at the major papilla.","The common hepatic duct runs in the hepatoduodenal ligament and joins the cystic duct to form the common bile duct , which passes behind the duodenum and through the head of the pancreas to the hepatopancreatic ampulla , opening into the descending duodenum at the major duodenal papilla , controlled by the sphincter of Oddi (accessible by endoscopy: stone extraction, sphincterotomy)."],"dp":[]},"anat2-biliary:e6":{"s":2,"u":["Gallbladder under segments 4b-5: fundus, body, neck; valve of Heister.","The gallbladder is a pear-shaped sac under segments 4b-5 , above the first part of the duodenum, with a fundus, body and neck ; the cystic duct contains the spiral valve of Heister ."],"dp":[{"h":"Note","t":"Gallbladder: fundus, body, neck; lies under segments 4b-5 ; the cystic duct has the spiral valve of Heister . The fundus projects at the tip of the 9th right costal cartilage (Murphy's sign)."}]},"anat2-biliary:e7":{"s":2,"u":["Hepatocystic triangle + cystic artery; critical view of safety.","The hepatocystic triangle (liver, cystic duct, common hepatic duct), crossed by the cystic artery (related to Calot's triangle), must be dissected to obtain the critical view of safety before clipping anything in a cholecystectomy."],"dp":[{"h":"Note","t":"Calot's (hepatocystic) triangle : cystic duct, common hepatic duct, inferior border of the liver; contains the cystic artery (usually from the right hepatic). Obtain the critical view of safety before clipping."}]},"anat2-biliary:e8":{"s":2,"u":["Cystic artery supplies the gallbladder.","The hepatocystic triangle (liver, cystic duct, common hepatic duct), crossed by the cystic artery (related to Calot's triangle), must be dissected to obtain the critical view of safety before clipping anything in a cholecystectomy."],"dp":[]},"anat2-biliary:e9":{"s":3,"u":["Sympathetic: storage, pain; vagus: release; right phrenic: Glisson's capsule.","Nerves : sympathetic (coeliac plexus: bile storage, visceral pain), parasympathetic (vagal trunks: bile release), and the right phrenic nerve to Glisson's capsule (somatic pain, referred to the right shoulder)."],"dp":[{"h":"Clinical","t":"Biliary colic/cholecystitis : RUQ pain referred to the right shoulder (phrenic) and inferior angle of the scapula. A stone in the CBD → obstructive jaundice; at the ampulla → gallstone pancreatitis ."}]}},"meta":{"10a6emm":{"a":"recall","vg":"anat2-biliary:e0/recall/1"},"10eq4kw":{"a":"recall","vg":"anat2-biliary:e0/recall/2"},"1n270u5":{"a":"recall","vg":"anat2-biliary:e0/recall/3"},"uejdil":{"a":"recall","vg":"anat2-biliary:e2/recall/1"},"1o62fxz":{"a":"recall","vg":"anat2-biliary:e3/recall/1"},"5ar0ej":{"a":"recall","vg":"anat2-biliary:e3/recall/2"},"s796rq":{"a":"recall","vg":"anat2-biliary:e4/recall/1"},"bynpm7":{"a":"recall","vg":"anat2-biliary:e5/recall/1"},"d0euts":{"a":"recall","vg":"anat2-biliary:e6/recall/1"},"x15h7n":{"a":"recall","vg":"anat2-biliary:e6/recall/2"},"1ufkve0":{"a":"recall","vg":"anat2-biliary:e7/recall/1"},"gubukb":{"a":"recall","vg":"anat2-biliary:e9/recall/1"}},"explRev":"260d9b355d85"};
